import { createClient } from '@supabase/supabase-js'

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL || 'https://placeholder.supabase.co'
const supabaseAnonKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY || 'placeholder-key'

let supabase: any = null

// Only create client if we have valid credentials
if (supabaseUrl && supabaseAnonKey &&
    !supabaseUrl.includes('placeholder') &&
    !supabaseAnonKey.includes('placeholder') &&
    supabaseUrl.startsWith('http')) {
  try {
    supabase = createClient(supabaseUrl, supabaseAnonKey, {
      auth: {
        autoRefreshToken: true,
        persistSession: true,
        detectSessionInUrl: true
      }
    })
    console.log('Supabase client initialized successfully')
  } catch (error) {
    console.warn('Failed to create Supabase client:', error)
  }
} else {
  console.warn('Supabase credentials not properly configured')
}

export { supabase }

// Auth functions
export const signUp = async (email: string, password: string) => {
  if (!supabase) return { error: 'Supabase not initialized' }
  return await supabase.auth.signUp({ email, password })
}

export const signIn = async (email: string, password: string) => {
  if (!supabase) return { error: 'Supabase not initialized' }
  return await supabase.auth.signInWithPassword({ email, password })
}

export const signOut = async () => {
  if (!supabase) return { error: 'Supabase not initialized' }
  return await supabase.auth.signOut()
}

export const getCurrentUser = async () => {
  if (!supabase) return null
  return await supabase.auth.getUser()
}

export const getSession = async () => {
  if (!supabase) return null
  return await supabase.auth.getSession()
}

// User roles and permissions
export const isAdmin = async () => {
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return false

  // Check if user has admin role in user metadata or a separate admins table
  const { data: adminUser } = await supabase
    .from('admins')
    .select('*')
    .eq('user_id', user.id)
    .single()

  return !!adminUser
}

// Comments functions
export interface Comment {
  id: string
  news_id: string
  user_id: string
  user_email: string
  user_name?: string
  content: string
  created_at: string
  updated_at: string
}

export const getCommentsByNewsId = async (newsId: string, includePending?: boolean): Promise<Comment[]> => {
  if (!supabase) return []

  let query = supabase
    .from('comments')
    .select('*')
    .eq('news_id', newsId)

  // Only show approved comments unless includePending is true
  if (!includePending) {
    query = query.eq('is_approved', true).eq('is_hidden', false)
  }

  try {
    const { data, error } = await query
      .order('created_at', { ascending: true })

    if (error) {
      return []
    }

    return data || []
  } catch (err: any) {
    return []
  }
}

export const addComment = async (newsId: string, content: string): Promise<Comment | null> => {
  if (!supabase) return null

  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return null

  const { data, error } = await supabase
    .from('comments')
    .insert([{
      news_id: newsId,
      user_id: user.id,
      user_email: user.email,
      user_name: user.user_metadata?.full_name || user.email?.split('@')[0],
      content: content.trim(),
    }])
    .select()
    .single()

  if (error) {
    console.error('Error adding comment:', error)
    return null
  }

  return data
}

export const updateComment = async (commentId: string, content: string): Promise<Comment | null> => {
  if (!supabase) return null

  const { data, error } = await supabase
    .from('comments')
    .update({ content: content.trim(), updated_at: new Date().toISOString() })
    .eq('id', commentId)
    .select()
    .single()

  if (error) {
    console.error('Error updating comment:', error)
    return null
  }

  return data
}

export const deleteComment = async (commentId: string): Promise<boolean> => {
  if (!supabase) return false

  const { error } = await supabase
    .from('comments')
    .delete()
    .eq('id', commentId)

  if (error) {
    console.error('Error deleting comment:', error)
    return false
  }

  return true
}

// Database types
export interface NewsItem {
  id: string
  title: string
  excerpt: string
  content: string
  category: string
  author: string
  featured: boolean
  published_at: string
  image_url: string
  images: string[] // Array of image URLs for slideshow
  video_url?: string // Optional video URL
  is_published?: boolean // Admin approval status
  is_draft?: boolean // Draft status
  slug: string
  created_at: string
  updated_at: string
  seo_title?: string // SEO meta title
  meta_description?: string // SEO meta description
  tags?: string[] // Article tags
  location_tags?: string[] // Location tags
  status?: 'draft' | 'published' | 'archived' | 'removed' // Document status
  scheduled_publish_at?: string // Scheduled publish time
  source?: string // News source
  views?: number // View count
  is_read?: boolean
  news_slug?: string
}

