export const addNews = async (news: Omit<NewsItem, 'id' | 'published_at' | 'slug' | 'created_at' | 'updated_at'>): Promise<NewsItem | null> => {
  if (!supabase) {
    console.error('Supabase client not initialized')
    return null
  }

  try {
    // Create a unique slug
    let slug = news.title.toLowerCase()
      .replace(/[^a-z0-9\s-]/g, '')
      .replace(/\s+/g, '-')
      .replace(/-+/g, '-')
      .trim()

    // Check if slug already exists and make it unique
    let counter = 1
    let originalSlug = slug
    while (true) {
      const { data: existing } = await supabase
        .from('news')
        .select('id')
        .eq('slug', slug)
        .single()

      if (!existing) break

      slug = `${originalSlug}-${counter}`
      counter++
    }

    const newsData = {
      title: news.title,
      excerpt: news.excerpt,
      content: news.content,
      category: news.category,
      author: news.author,
      featured: news.featured,
      image_url: news.image_url,
      images: news.images || [],
      video_url: news.video_url || null,
      is_published: news.is_published || false,
      is_draft: news.is_draft || false,
      slug,
      published_at: news.is_published ? new Date().toISOString() : null,
    }

    console.log('Adding news with data:', newsData)

    const { data, error } = await supabase
      .from('news')
      .insert([newsData])
      .select()
      .single()

    if (error) {
      console.error('Supabase insert error:', error)
      console.error('Error code:', error.code)
      console.error('Error message:', error.message)
      console.error('Error details:', error.details || 'No details available')
      console.error('Error hint:', error.hint || 'No hint available')
      return null
    }

    console.log('News added successfully:', data)
    return data
  } catch (err) {
    console.error('Unexpected error in addNews:', err)
    if (err instanceof Error) {
      console.error('Error name:', err.name)
      console.error('Error message:', err.message)
      console.error('Error stack:', err.stack)
    }
    return null
  }
}

export const saveDraft = async (news: Partial<NewsItem>): Promise<boolean> => {
  if (!supabase) {
    console.error('Supabase client not initialized')
    return false
  }

  try {
    // Create a unique slug for drafts
    let slug = `draft-${(news.title || 'untitled').toLowerCase()
      .replace(/[^a-z0-9\s-]/g, '')
      .replace(/\s+/g, '-')
      .replace(/-+/g, '-')
      .trim()}-${Date.now()}`

    const draftData = {
      title: news.title,
      excerpt: news.excerpt,
      content: news.content,
      category: news.category,
      author: news.author,
      featured: news.featured,
      image_url: news.image_url,
      images: news.images || [],
      video_url: news.video_url || null,
      is_published: news.is_published || false,
      is_draft: news.is_draft || true,
      slug,
      published_at: null, // Drafts don't have published_at
    }

    console.log('Saving draft with data:', draftData)

    const { data, error } = await supabase
      .from('news')
      .insert([draftData])
      .select()
      .single()

    if (error) {
      console.error('Supabase insert error for draft:', error)
      return false
    }

    console.log('Draft saved successfully:', data)
    return true
  } catch (err) {
    console.error('Unexpected error in saveDraft:', err)
    return false
  }
}

