// Search function
export const searchNews = async (query: string): Promise<NewsItem[]> => {
  if (!supabase || !query.trim()) return []
  
  try {
    // SQL Injection koruması: Özel karakterleri escape et ve uzunluk sınırı koy
    const sanitizedQuery = query
      .replace(/[%_]/g, '\\$&') // % ve _ karakterlerini escape et (PostgreSQL LIKE için)
      .trim()
      .substring(0, 100) // Maksimum uzunluk sınırı
    
    // RLS policy zaten filtreliyor - query'de filtreleme yapmıyoruz
    const { data, error } = await supabase
      .from('news')
      .select('*')
      .or(`title.ilike.%${sanitizedQuery}%,excerpt.ilike.%${sanitizedQuery}%,content.ilike.%${sanitizedQuery}%`)
      .order('published_at', { ascending: false })
      .limit(20)
    
    if (error) {
      console.error('❌ Error searching news:', {
        code: error.code,
        message: error.message,
        details: error.details
      })
      return []
    }
    
    return data || []
  } catch (err: any) {
    // Sessizce boş array döndür
    return []
  }
}