// Home page
import React from 'react';
import HeroSection from '@/components/ui/HeroSection';
import NewsCard from '@/components/ui/NewsCard';
import Sidebar from '@/components/layout/Sidebar';
import WhatsAppTipLine from '@/components/ui/WhatsAppTipLine';
import { getAllNews, getFeaturedNews } from '@/lib/supabase';

// Revalidate every 60 seconds for ISR
export const revalidate = 60;

const HomePage: React.FC = async () => {
  // Hata yönetimi ile haberleri getir
  let allNews: any[] = [];
  let featuredNews: any[] = [];
  
  try {
    allNews = await getAllNews() || [];
  } catch (error) {
    allNews = [];
  }
  
  try {
    featuredNews = await getFeaturedNews() || [];
  } catch (error) {
    featuredNews = [];
  }

  // If no news, show empty state
  if (allNews.length === 0) {
    return (
      <div className="min-h-screen bg-background">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-16">
          <div className="text-center">
            <h1 className="text-4xl font-bold text-gray-900 mb-4">Henüz Haber Yok</h1>
            <p className="text-gray-600 mb-8">Admin panelinden ilk haberinizi ekleyin.</p>
            <a href="/admin" className="bg-primary text-white px-6 py-3 rounded-lg hover:bg-blue-700 transition">
              Admin Paneline Git
            </a>
          </div>
        </div>
      </div>
    );
  }

  const categories = ['Gündem', 'Siyaset', 'Ekonomi', 'Spor', 'Magazin'];

  return (
    <div className="min-h-screen bg-background">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
          {/* Main Content */}
          <div className="lg:col-span-3">
            {/* Hero Section */}
            <HeroSection />

            {/* News Grid */}
            <section className="mt-12">
              <h2 className="text-2xl font-bold text-primary mb-6">Son Haberler</h2>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {allNews.slice(0, 9).map((news) => (
                  <NewsCard
                    key={news?.id || Math.random()}
                    title={news?.title || 'Haber Başlığı'}
                    category={news?.category || 'Gündem'}
                    publishedAt={news?.published_at ? new Date(news.published_at).toLocaleDateString('tr-TR') : new Date().toLocaleDateString('tr-TR')}
                    imageUrl={news?.image_url || 'https://picsum.photos/400/300?random=1'}
                    slug={news?.slug}
                    excerpt={news?.excerpt}
                  />
                ))}
              </div>
            </section>

            {/* Category Sections */}
            {categories.map((category) => {
              const categoryNews = allNews.filter(n => n.category === category).slice(0, 3);
              if (categoryNews.length === 0) return null;

              return (
                <section key={category} className="mt-12">
                  <h2 className="text-2xl font-bold text-primary mb-6">{category}</h2>
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {categoryNews.map((news) => (
                      <NewsCard
                        key={news?.id || Math.random()}
                        title={news?.title || 'Haber Başlığı'}
                        category={news?.category || 'Gündem'}
                        publishedAt={news?.published_at ? new Date(news.published_at).toLocaleDateString('tr-TR') : new Date().toLocaleDateString('tr-TR')}
                        imageUrl={news?.image_url || 'https://picsum.photos/400/300?random=1'}
                        slug={news?.slug}
                        excerpt={news?.excerpt}
                      />
                    ))}
                  </div>
                </section>
              );
            })}
          </div>

          {/* Sidebar */}
          <div className="lg:col-span-1">
            <Sidebar />
          </div>
        </div>

        {/* WhatsApp Tip Line */}
        <WhatsAppTipLine />
      </div>
    </div>
  );
};

export default HomePage;